def choose_move(observation):
    # Simple deterministic move toward nearest resource if available, else toward center, constrained to [-1,0,1]
    def get(field, default=None):
        try:
            if isinstance(observation, dict):
                return observation.get(field, default)
            return getattr(observation, field, default)
        except Exception:
            return default

    wx = get("grid_width", 0)
    wy = get("grid_height", 0)
    sx = get("self_position", None)
    ox = get("opponent_position", None)
    if isinstance(sx, (list, tuple)) and len(sx) >= 2:
        sx, sy = int(sx[0]), int(sx[1])
    else:
        sx, sy = 0, 0
    if isinstance(ox, (list, tuple)) and len(ox) >= 2:
        ox, oy = int(ox[0]), int(ox[1])
    else:
        ox, oy = 0, 0

    resources = get("resources", [])
    obstacles = get("obstacles", [])
    rem = get("remaining_resource_count", 0)

    # best guess: pick a target resource closest to self
    tx, ty = None, None
    bestd = None
    for r in resources:
        if not isinstance(r, (list, tuple)) or len(r) < 2:
            continue
        rx, ry = int(r[0]), int(r[1])
        d = abs(rx - sx) + abs(ry - sy)
        if bestd is None or d < bestd:
            bestd = d
            tx, ty = rx, ry

    if tx is None:
        # fallback: move toward center of grid
        tx = max(0, min(wx - 1, wx // 2))
        ty = max(0, min(wy - 1, wy // 2))

    dx = 0
    dy = 0
    if tx > sx:
        dx = 1
    elif tx < sx:
        dx = -1
    if ty > sy:
        dy = 1
    elif ty < sy:
        dy = -1

    # avoid stepping into an obstacle if possible
    nx, ny = sx + dx, sy + dy
    if any((nx == ob[0] and ny == ob[1]) for ob in obstacles if isinstance(ob, (list, tuple)) and len(ob) >= 2):
        dx, dy = 0, 0
        # try alternatives
        if tx == sx:
            if ty > sy:
                dy = 1
            elif ty < sy:
                dy = -1
        elif ty == sy:
            if tx > sx:
                dx = 1
            elif tx < sx:
                dx = -1
        nx, ny = sx + dx, sy + dy
        if any((nx == ob[0] and ny == ob[1]) for ob in obstacles if isinstance(ob, (list, tuple)) and len(ob) >= 2):
            dx, dy = 0, 0

    return [dx, dy]
